ờng Tăng Nhơn Phú, TP. Hồ Chí Minh","address_old":"Gian 01-02-03, Đường Hồ Thị Tư, TP Thủ Đức cũ, TP.HCM cũ","category":"nha_sach"},{"name":"Nhà sách Phương Nam - Hoàng Việt","street":"44 Hoàng Việt","ward":"Tân Sơn Nhất","district":"Quận Tân Bình","phone":"0915807227","source":"https://nhasachphuongnam.com/pages/he-thong-nha-sach-phuong-nam","key":"official:hcm:round1:phuong:nam:hoang:viet:44:hoang:viet","address_new":"44 Hoàng Việt, phường Tân Sơn Nhất, TP. Hồ Chí Minh","address_old":"44 Hoàng Việt, Quận Tân Bình cũ, TP.HCM cũ","category":"nha_sach"},{"name":"Nhà sách Phương Nam - Công viên Bình Phú","street":"Công viên Bình Phú, 10-12 Bình Phú","ward":"Bình Phú","district":"Quận 6","phone":"0916740133","source":"https://nhasachphuongnam.com/pages/he-thong-nha-sach-phuong-nam","key":"official:hcm:round1:phuong:nam:cong:vien:binh:phu:cong:vien:binh:phu:10:12:binh:phu","address_new":"Công viên Bình Phú, 10-12 Bình Phú, phường Bình Phú, TP. Hồ Chí Minh","address_old":"Công viên Bình Phú, 10-12 Bình Phú, Quận 6 cũ, TP.HCM cũ","category":"nha_sach"}]'::jsonb) AS s(name text,street text,ward text,district text,phone text,source text,key text,address_new text,address_old text,category text) WHERE s.source LIKE 'https://%' AND s.category='nha_sach' AND s.address_new LIKE '% '||s.ward||', TP. Hồ Chí Minh' AND (s.phone IS NULL OR s.phone~'^[0-9]{8,11}$')
 AND EXISTS (SELECT 1 FROM public.sales_hcm_old_wards w WHERE w.province='TP Hồ Chí Minh' AND w.ward_new=s.ward AND w.legacy_district=s.district AND w.active)
 AND NOT EXISTS (SELECT 1 FROM public.field_prospects p WHERE p.research_source_key=s.key OR lower(btrim(p.address_line))=lower(btrim(s.address_new)) OR (p.province='TP Hồ Chí Minh' AND p.ward_new=s.ward AND lower(btrim(p.name))=lower(btrim(s.name))) OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone))
 AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE lower(btrim(c.address_line))=lower(btrim(s.address_new)) OR (c.province='TP Hồ Chí Minh' AND lower(btrim(c.name))=lower(btrim(s.name))) OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))), inserted AS (
 INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,address_legacy,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch,google_maps_url,google_place_id)
 SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_new,'TP Hồ Chí Minh',s.district,s.ward,s.address_old,s.category,s.phone,NULL,
 'Nguồn chính thức tra cứu 22/11/2026: hệ thống nhà sách công bố địa điểm bán lẻ. CHƯA GHÉ / CHƯA XÁC MINH hoạt động, bảng hiệu và GPS thực địa. Nguồn: '||s.source,
 'new','manual',s.key,s.source,'2026-11-22-hcm-old-round1-official-books-179',NULL,NULL
 FROM vetted s
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING ward_new,district,name,category,phone)
SELECT ward_new,district,name,category,phone FROM inserted ORDER BY district,ward_new,name;
